{
  "ParentPolicyName": "Karnataka Electric Vehicle and Energy Storage Policy 2017",
  "PolicyInformation": [
    {
      "PolicyName": "Karnataka Clean Mobility Policy 2025-30",
      "Category": "Industrial Policy",
      "Industry": "Clean Mobility",
      "SubIndustry": "Electric Vehicles, Hydrogen Based Vehicles, Fuel Cell Based Vehicles, Battery Manufacturing, Component Manufacturing, Charging Infrastructure, Battery Recycling, Testing Infrastructure",
      "BusinessSize": "Micro Enterprise, Small Enterprise, Medium Enterprise, Large Enterprise, Mega Enterprise, Ultra Mega Enterprise",
      "Geography": "Karnataka",
      "Year": [
        "2025-2030"
      ],
      "SpecialAttributes": [
        "Clean Mobility Clusters",
        "Research & Development Support",
        "Skill Development",
        "Sustainable Industrialization",
        "Circular Economy"
      ],
      "Keywords": [
        "Clean Mobility",
        "Electric Vehicle",
        "EV",
        "Hydrogen Fuel Cell",
        "Battery Manufacturing",
        "Charging Infrastructure",
        "Karnataka",
        "Incentives"
      ],
      "PolicySummary": "The Karnataka Clean Mobility Policy 2025-30 aims to establish Karnataka as a premier destination for clean mobility vehicle manufacturing across the entire value chain. It seeks to attract investments of INR 50,000 crore and generate approximately 100,000 jobs. The policy supports the manufacturing of electric vehicles, hydrogen-based vehicles, fuel cells, battery packs, components, charging infrastructure, and promotes battery recycling and R&D. Key strategies include providing comprehensive incentives, establishing dedicated Clean Mobility clusters with ready-to-use infrastructure, developing a robust charging network, and fostering skill development to create a comprehensive and sustainable ecosystem. This policy supersedes the Karnataka Electric Vehicle and Energy Storage Policy 2017.",
      "EligibilityCriteria": "Investments made during the policy period (from 11.02.2025 for 5 years) in the following activities/products are eligible for incentives:\n1.  **Clean mobility vehicle and components:** Manufacturing/Assembly of Electric Vehicles (fixed/swappable battery), hydrogen-based vehicles, and fuel cell-based electric vehicles. Manufacturing of clean mobility cells, battery packs/modules (Li-ion, fuel cells, hydrogen cells), and various vehicle components like electric motors, controllers, battery systems, etc.\n2.  **Li-ion & fuel cell components:** Manufacturing of Cathode Active Materials, Anode Materials, Separators, Carbonate Solvents, processing of minerals for Li-ion, and consumables like packaging foil and casings.\n3.  **Infrastructure Equipment:** Manufacturing of Electric Vehicle Charging/Swapping Infrastructure Equipment and Hydrogen stations.\n4.  **Recycling:** Re-use and Recycling of batteries through centers set up by clean mobility battery manufacturers and other players.\n5.  **Testing:** Clean Mobility vehicle testing facilities for battery/cell materials and components.\n**Condition:** Components manufacturers shall supply a minimum of 50% of their products to EV and clean mobility OEMs.",
      "IncentivesAndBenefits": [
        {
          "IncentiveName": "Demand Side Incentives",
          "Description": "Incentives aimed at encouraging the adoption of clean mobility vehicles by consumers.",
          "Benefits": {
            "Road Tax and Registration Charges Exemption": "Exemption from payment of taxes on all categories of electric vehicles (both transport and non-transport), including e-rickshaws and e-carts. This exemption does not apply to motor cars, jeeps, omni buses, and private service vehicles run on electricity costing more than Rs. 25 lakhs."
          }
        },
        {
          "IncentiveName": "Capital Subsidy for Micro, Small and Medium Enterprises (MSMEs)",
          "Description": "Investment promotion subsidy for new or expansion projects by MSMEs, based on the Value of Fixed Assets (VFA) and zonal classification. The subsidy is disbursed in installments.",
          "Benefits": {
            "Micro Industries (General)": "Zone 1: 30% of VFA (max INR 30 Lakh), Zone 2: 25% of VFA (max INR 25 Lakh), Zone 3: 20% of VFA (max INR 10 Lakh). Disbursed in 2 installments.",
            "Micro Industries (Special Category - SC/ST, Women, Minorities, etc.)": "Zone 1: 35% of VFA (max INR 35 Lakh), Zone 2: 30% of VFA (max INR 30 Lakh), Zone 3: 25% of VFA (max INR 15 Lakh). Disbursed in 2 installments.",
            "Small Industries (General)": "Zone 1: 25% of VFA (max INR 200 Lakh), Zone 2: 20% of VFA (max INR 150 Lakh), Zone 3: 20% of VFA (max INR 50 Lakh). Disbursed in 2 installments.",
            "Small Industries (Special Category)": "Zone 1: 30% of VFA (max INR 225 Lakh), Zone 2: 25% of VFA (max INR 175 Lakh), Zone 3: 25% of VFA (max INR 75 Lakh). Disbursed in 2 installments.",
            "Medium Industries": "Zone 1: 25% of VFA (max INR 10 Cr), Zone 2: 20% of VFA (max INR 8 Cr), Zone 3: 20% of VFA (max INR 4 Cr). Disbursed in 4 annual equal disbursements."
          }
        },
        {
          "IncentiveName": "Concessions on Stamp Duty and Registration for MSMEs",
          "Description": "Fiscal concessions to reduce the initial setup cost for MSMEs.",
          "Benefits": {
            "Exemption from Stamp Duty": "100% exemption in all zones for loan agreements, credit deeds, mortgage deeds, and lease/sale deeds executed with government industrial agencies or for lands purchased under Sec 109 of the KLR Act, 1961.",
            "Concessional Registration Charges": "A concessional rate of INR 1 per INR 1,000 for registration charges in all zones."
          }
        },
        {
          "IncentiveName": "Other Concessions for MSMEs",
          "Description": "Additional financial support and reimbursements for MSMEs.",
          "Benefits": {
            "Reimbursement of Land Conversion Fee": "100% reimbursement of land conversion fees in all zones.",
            "Exemption of Tax on Electricity Tariff": "100% tax exemption for a specified period. General Category: 7 years in Zone 1, 6 years in Zone 2, 3 years in Zone 3. Special Category: 8 years in Zone 1, 7 years in Zone 2, 4 years in Zone 3.",
            "Subsidy for setting up ETP": "Subsidy for Effluent Treatment Plant. General Category: 50% of cost (max INR 50 Lakh). Special Category: 75% of cost (max INR 60 Lakh)."
          }
        },
        {
          "IncentiveName": "Incentives and Concessions for Large/Mega/Ultra Mega Enterprises",
          "Description": "A standard package of incentives for large-scale investments in the clean mobility sector.",
          "Benefits": {
            "Capital Investment Subsidy": "Zone 1: 25% of VFA, Zone 2: 20% of VFA, Zone 3: 20% of VFA. Disbursed over 5 equal annual installments. VFA includes land, building, plant & machinery. Land cost is considered only for districts other than Bengaluru Urban and Bengaluru Rural, up to 50 acres.",
            "Exemption of Stamp Duty": "100% exemption on stamp duty for loan agreements, lease/sale deeds with government agencies.",
            "Concessional Registration Charges": "A concessional rate of Rs. 1.00 per Rs. 1,000.",
            "Reimbursement of Land Conversion Fee": "100% reimbursement of the fee for converting land from agricultural to industrial use.",
            "Subsidy for setting up Effluent Treatment Plant (ETP)": "One-time capital subsidy up to 50% of the cost of ETPs, subject to a ceiling of Rs. 250.00 lakhs."
          }
        },
        {
          "IncentiveName": "Incentives for Charging and Hydrogen Stations",
          "Description": "Capital subsidy to promote the establishment of a robust network of charging and filling stations across all zones. No incentives are provided for slow charging stations.",
          "Benefits": {
            "Fast Charging Stations (for 2W, 3W, Cars, Buses)": "Capital Subsidy of 25%, up to Rs. 10,00,000 per station. Available for the first 500 stations.",
            "Battery Switching/Swapping Stations (2W, 3W)": "Capital Subsidy of 25%, up to Rs. 3,00,000 per station. Available for the first 500 stations.",
            "Battery Switching/Swapping Stations (Cars)": "Capital Subsidy of 25%, up to Rs. 5,00,000 per station. Available for the first 200 stations.",
            "Battery Switching/Swapping Stations (Buses)": "Capital Subsidy of 25%, up to Rs. 10,00,000 per station. Available for the first 200 stations.",
            "Hydrogen Stations": "Capital Subsidy of 25%, up to Rs. 1 Crore per station. Available for the first 25 stations."
          }
        },
        {
          "IncentiveName": "Support for Research & Skill Development",
          "Description": "Incentives to encourage R&D, innovation, and skill enhancement in the clean mobility sector.",
          "Benefits": {
            "R&D Cost Reimbursement": "For enterprises achieving world-class benchmarks in Advanced Chemistry Batteries, reimbursement of 30% of the R&D cost, subject to a maximum of Rs 1.00 crore. This is for the first such enterprise operating in the state.",
            "Venture Capital Fund": "A venture capital fund will be set up for research in clean mobility, advanced chemistry batteries, and battery management systems.",
            "Skill Development Initiatives": "Enhancing ITI curriculum, fostering collaboration between industry and academia for clean mobility-focused courses, and encouraging partnerships with international universities."
          }
        }
      ]
    }
  ],
  "PolicyGoals": [
    "To attract investments of Rs 50,000 Cr across the entire clean mobility vehicle value chain and generate approximately 100,000 new jobs during the Policy Period.",
    "Making Karnataka #1 in Asia in Future Clean Mobility, fueled by Equitable and Sustainable Development.",
    "Accelerating Clean Mobility Vehicle Adoption in Karnataka through a Robust Charging Infrastructure Network or hydrogen stations.",
    "Create a Clean Mobility Vehicle ecosystem that fosters innovation in the State of Karnataka.",
    "To position Karnataka as the premier destination for Clean Mobility Vehicle manufacturing, spanning the entire value chain from battery and cell manufacturing to R&D."
  ]
}
